import { useId } from "react";

// Ramnn's marks, one ink (currentColor), from mint-pocs' brand files. Pure
// SVG: they render on the server and in any appearance.

type MarkProps = {
  readonly className?: string;
  /** The accessible name; without it the mark is decorative. */
  readonly title?: string;
};

const labelled = (title: string | undefined) =>
  title === undefined
    ? { "aria-hidden": true as const }
    : { role: "img" as const, "aria-label": title };

