/**
 * Ramnn's picto: the back folder at 40%, the front one full, the eyes' whites
 * and glints cut out so the ground shows through them. Sized by CSS (viewBox
 * 131.6 x 101.63). The mask ids are per instance: two pictos on a page must
 * not share them.
 */
export function RamnnPicto({ className, title }: MarkProps) {
  const id = useId();
  const eyes = `${id}-eyes`;
  const glints = `${id}-glints`;
  const left = `${id}-eye-l`;
  const right = `${id}-eye-r`;
  return (
    <svg
      className={className}
      viewBox="0 0 131.6 101.63"
      fill="currentColor"
      {...labelled(title)}
    >
      <defs>
        <mask
          id={eyes}
          maskUnits="userSpaceOnUse"
          x="0"
          y="0"
          width="131.6"
          height="101.63"
        >
          <rect width="131.6" height="101.63" fill="#fff" />
          <ellipse
            cx="55.54"
            cy="65.74"
            rx="13.61"
            ry="15.93"
            transform="rotate(5.13 55.54 65.74)"
            fill="#000"
          />
          <ellipse
            cx="95.92"
            cy="69.74"
            rx="13.61"
            ry="15.93"
            transform="rotate(5.13 95.92 69.74)"
            fill="#000"
          />
        </mask>
        <clipPath id={left}>
          <ellipse
            cx="55.54"
            cy="65.74"
            rx="13.61"
            ry="15.93"
            transform="rotate(5.13 55.54 65.74)"
          />
        </clipPath>
        <clipPath id={right}>
          <ellipse
            cx="95.92"
            cy="69.74"
            rx="13.61"
            ry="15.93"
            transform="rotate(5.13 95.92 69.74)"
          />
        </clipPath>
        <mask
          id={glints}
          maskUnits="userSpaceOnUse"
          x="0"
          y="0"
          width="131.6"
          height="101.63"
        >
          <rect width="131.6" height="101.63" fill="#fff" />
          <circle cx="57.91" cy="54.68" r="2.17" fill="#000" />
          <circle cx="98.28" cy="58.68" r="2.17" fill="#000" />
        </mask>
      </defs>
      <path
        opacity="0.4"
        d="M131.6,31.96V10.93L59.06.16c-7.93-1.18-15.31,4.3-16.49,12.23l-.9,6.09,87.8,13.03c.73.11,1.44.27,2.14.45Z"
      />
      <path
        mask={`url(#${eyes})`}
        d="M126.76,101.63c2.67,0,4.84-2.17,4.84-4.84V31.96c-.7-.19-1.41-.34-2.14-.45L31.85,17.02c-10.43-1.55-20.13,5.65-21.68,16.08L0,101.6c.11,0,.2.03.31.03h126.45Z"
      />
      <g mask={`url(#${glints})`}>
        <ellipse
          clipPath={`url(#${left})`}
          cx="62.02"
          cy="60.47"
          rx="10.66"
          ry="11.51"
          transform="rotate(5.13 62.02 60.47)"
        />
        <ellipse
          clipPath={`url(#${right})`}
          cx="102.39"
          cy="64.47"
          rx="10.66"
          ry="11.51"
          transform="rotate(5.13 102.39 64.47)"
        />
      </g>
    </svg>
  );
}
